def money(n): return '₹'+format(n,',')
def row(r,time=False):
    name,cat,amount,ic=r
    return f'<button class="transaction" data-category="{cat}"><span class="category {cat.lower().replace(" ","-").replace("&","")}">{icon(ic)}</span><span class="copy"><strong>{name}</strong><small>{cat} · Cash'+(' · 6:55 pm' if time else '')+f'</small></span><b>−{money(amount)}</b></button>'
def day(n,weekday,amount,rr,time=False):
    return f'<section class="day"><button class="day-head" aria-label="Collapse {n} October" onclick="this.parentNode.classList.toggle(\'collapsed\')"><b>{n}</b><span>{weekday}<br>October</span><strong>−{money(amount)}</strong>'+ (f'<span class="collapse">{icon("up")}</span>' if time else '')+'</button><div class="day-rows">'+''.join(row(r,time) for r in rr)+'</div></section>'
