html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tally · Sage Expressive</title><style>'+css+'</style><body><header><h1>Tally / Sage Expressive</h1><p>Home, Transactions, Insights · Light + dark · 390 × 844</p><p class="note">Design reference using only the supplied screenshot data. Scroll inside each phone; navigation links connect screens in the same mode.</p></header><main>'
for mode in ('light','dark'):
    for key,title,body in [('home','Home',home),('transactions','Transactions',transactions),('insights','Insights',insights)]:
        fab='' if key=='insights' else f'<button class="fab {"square" if key=="transactions" else ""}" aria-label="Add transaction">{icon("plus")}{"Add" if key=="home" else ""}</button>'
        html+=f'<article class="frame"><p>{title} / {mode.capitalize()}</p><section id="{key}-{mode}" class="phone {mode}" aria-label="{title} {mode}"><div class="content">{body}</div>{fab}{nav(key).replace("MODE",mode)}</section></article>'
html+='''</main><script>
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const phone=button.closest('.phone');phone.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===button));const filter=button.dataset.filter;phone.querySelectorAll('.transaction').forEach(row=>{row.hidden=!(filter==='All'||row.dataset.category===filter||filter==='Food'&&['Fruits','Meat & Fish','Snacks'].includes(row.dataset.category));row.style.display=row.hidden?'none':'flex'});phone.querySelectorAll('.day').forEach(day=>day.style.display=[...day.querySelectorAll('.transaction')].some(row=>!row.hidden)?'block':'none')}));
</script></body></html>'''
(root/'index.html').write_text(html)
print(root/'index.html')
